{"path": "parser.mjs", "content": "const SKU_PATTERN = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_PATTERN = /^[0-9]+$/;

function parseSafeInteger(value, label) {
  if (!DIGITS_PATTERN.test(value)) {
    throw new Error(`Invalid ${label}: ${JSON.stringify(value)}`);
  }
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed)) {
    throw new RangeError(`${label} exceeds Number.MAX_SAFE_INTEGER`);
  }
  return parsed;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }

  const orders = [];
  for (const rawLine of text.split('\n')) {
    const line = rawLine.replace(/\r$/, '');
    if (line.trim() === '') {
      continue;
    }

    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Malformed row: ${JSON.stringify(line)}`);
    }

    const sku = fields[0].trim();
    const quantityText = fields[1].trim();
    const unitPriceText = fields[2].trim();

    if (!SKU_PATTERN.test(sku)) {
      throw new Error(`Invalid SKU: ${JSON.stringify(sku)}`);
    }

    const quantity = parseSafeInteger(quantityText, 'quantity');
    if (quantity <= 0) {
      throw new Error(`Invalid quantity: ${JSON.stringify(quantityText)}`);
    }

    const unitPriceCents = parseSafeInteger(unitPriceText, 'unitPriceCents');

    orders.push({ sku, quantity, unitPriceCents });
  }

  return orders;
}
