{"path": "report.mjs", "content": "import { parseOrders } from './parser.mjs';

export function buildReport(text) {
  const rows = parseOrders(text);

  const bySku = new Map();
  let totalUnits = 0;
  let totalCents = 0;

  for (const row of rows) {
    const lineCents = row.quantity * row.unitPriceCents;
    if (!Number.isSafeInteger(lineCents)) {
      throw new RangeError('cents total exceeds Number.MAX_SAFE_INTEGER');
    }

    const nextUnits = totalUnits + row.quantity;
    if (!Number.isSafeInteger(nextUnits)) {
      throw new RangeError('quantity total exceeds Number.MAX_SAFE_INTEGER');
    }
    totalUnits = nextUnits;

    const nextCents = totalCents + lineCents;
    if (!Number.isSafeInteger(nextCents)) {
      throw new RangeError('cents total exceeds Number.MAX_SAFE_INTEGER');
    }
    totalCents = nextCents;

    const existing = bySku.get(row.sku);
    if (existing === undefined) {
      bySku.set(row.sku, { sku: row.sku, quantity: row.quantity, totalCents: lineCents });
    } else {
      const itemUnits = existing.quantity + row.quantity;
      if (!Number.isSafeInteger(itemUnits)) {
        throw new RangeError('quantity total exceeds Number.MAX_SAFE_INTEGER');
      }
      const itemCents = existing.totalCents + lineCents;
      if (!Number.isSafeInteger(itemCents)) {
        throw new RangeError('cents total exceeds Number.MAX_SAFE_INTEGER');
      }
      existing.quantity = itemUnits;
      existing.totalCents = itemCents;
    }
  }

  const items = [...bySku.values()].sort((a, b) => (a.sku < b.sku ? -1 : a.sku > b.sku ? 1 : 0));

  return { items, totalUnits, totalCents };
}
